let result = 0;
let i = 0;

if (tokens[0] === '-') {
  result = -parseFloat(tokens[1]);
  i = 2;
} else {
  result = parseFloat(tokens[0]);
  i = 1;
}

for (; i < tokens.length; i += 2) {
  const operator = tokens[i];
  const nextValue = parseFloat(tokens[i + 1]);

  if (operator === '+') {
    result += nextValue;
  } else if (operator === '-') {
    result -= nextValue;
  } else if (operator === '*') {
    result *= nextValue;
  } else if (operator === '/') {
    result /= nextValue;
  }
}

    for (let i = 1; i < tokens.length; i += 2) {
      const operator = tokens[i];
      const nextValue = parseFloat(tokens[i + 1]);

      switch (operator) {
        case '+':
          result += nextValue;
          break;
        case '-':
          result -= nextValue;
          break;
        case '*':
          result *= nextValue;
          break;
        case '/':
          if (nextValue === 0) {
            throw new Error('Division by zero');
