}

for (; i < tokens.length; i += 2) {
  const operator = tokens[i];
  const nextValue = parseFloat(tokens[i + 1]);

  if (operator === '+') {
    result += nextValue;
  } else if (operator === '-') {
    result -= nextValue;
  } else if (operator === '*') {
    result *= nextValue;
  } else if (operator === '/') {
