const Matrix = require('./s3_matrix.js');

// Test scalar multiplication
const matrix1 = new Matrix([[1, 2], [3, 4]]);
const result1 = matrix1.mul(2);
console.assert(result1.toArray().toString() === [[2, 4], [6, 8]].toString(), 'Test 1 failed');

// Test matrix multiplication
const matrix2 = new Matrix([[1, 0], [0, 1]]);
const matrix3 = new Matrix([[2, 3], [4, 5]]);
const result2 = matrix2.mul(matrix3);
console.assert(result2.toArray().toString() === [[2, 3], [4, 5]].toString(), 'Test 2 failed');

// Test matrix multiplication with incompatible dimensions
try {
  const matrix4 = new Matrix([[1, 2], [3, 4]]);
  const matrix5 = new Matrix([[1, 2, 3], [4, 5, 6]]);
  matrix4.mul(matrix5);
  console.assert(false, 'Test 3 failed');
} catch (e) {
  console.assert(e.message === 'Inner dimensions do not match for matrix multiplication', 'Test 3 failed');
}

console.log('All tests passed');

