  const titles = library.titles();
  return titles.length > 0 ? titles.join(', ') : '(empty)';
}

function memberLine(library, member) {
  const loans = library.loans[member];
  if (loans && loans.length > 0) {
    return `member: ${loans.join(', ')}`;
  } else {
    return 'member: none';
  }
}

module.exports = {
  shelfLine,
  memberLine
};

