    return function(isbn) {
        if (cache.has(isbn)) {
            return cache.get(isbn);
        }
        const availability = availability(library, isbn);
        cache.set(isbn, availability);
        return availability;
    };
  const loans = library.loans[member];
  if (loans && loans.length > 0) {
    return `member: ${loans.join(', ')}`;
  } else {
    return 'member: none';
  }
}

module.exports = {
  shelfLine,
  memberLine
};

