    def has_cycle(self):
        visited = set()
        rec_stack = set()

        def dfs(node):
            if node in rec_stack:
                return True
            if node in visited:
                return False

            visited.add(node)
            rec_stack.add(node)

            for neighbor, _ in self.neighbors(node):
                if dfs(neighbor):
                    return True

            rec_stack.remove(node)
            return False

        for node in self.nodes:
            if dfs(node):
                return True

